using System.Net;
using System.Text;
using System.Text.Json;

namespace SwirStreamAI;

// Controlled documents contain fixture-only data. Optional network checks read
// public documents, never authenticate, fetch portal APIs or claim video decode.
public static class SourceExplorerTests
{
    const string Home="https://publisher.example/",Portal=Home+"stalker_portal/c/index.html";
    const string PortalHtml="<html><title>stalker_portal</title><script src='xpcom.common.js'></script><body>STB</body></html>";
    const string Playlist="#EXTM3U\n#EXTINF:-1 tvg-id=\"News.pl\" tvg-country=\"PL\",News\nhttps://cdn.example/live/news/hls/master.m3u8\n";
    const string Hls="#EXTM3U\n#EXT-X-TARGETDURATION:6\n#EXT-X-MEDIA-SEQUENCE:1\n#EXTINF:6,\nhttps://cdn.example/one.ts\n";
    const string Dash="<MPD xmlns='urn:mpeg:dash:schema:mpd:2011'><Period><AdaptationSet><Representation id='v'><BaseURL>https://cdn.example/video.mp4</BaseURL></Representation></AdaptationSet></Period></MPD>";
    static WebDocument Document(string url,string body,string type="text/html",DateTimeOffset? modified=null)=>new(url,body,type,modified);
    static SourceCandidate Candidate(string url,string title="Fixture source")=>new(SourceExplorerRules.Id(url),SourceCandidateKind.ProviderPage,url,title,url,DateTimeOffset.UtcNow,null,SourceExplorerRules.Digest("fixture document"),"Odczytano stronę; bez potwierdzenia transmisji.");
    static SourceExplorerResult Batch(params SourceCandidate[] values)=>new(values.ToList(),[],[],true);
    public static int Run(string report,bool network=false)=>RunAsync(report,network).GetAwaiter().GetResult();
    static async Task<int> RunAsync(string report,bool network)
    {
        string full=Path.GetFullPath(report);Directory.CreateDirectory(Path.GetDirectoryName(full)!);
        string root=Path.Combine(Path.GetDirectoryName(full)!,"explorer-fixtures-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);
        var checks=new List<object>();bool success=true;
        void Check(string name,bool ok,object? detail=null){checks.Add(new{name,ok,detail});success&=ok;}
        async Task Case(string name,Func<Task<bool>> action){try{Check(name,await action());}catch(Exception error){Check(name,false,new{errorType=error.GetType().Name});}}
        async Task<SourceExplorerResult> Analyze(string body,string path="fixture",DateTimeOffset? modified=null)
        {var explorer=new SourceExplorer((url,ct)=>Task.FromResult(Document(url,body,"text/html",modified)));return await explorer.Analyze(Home+path,[],[],CancellationToken.None);}

        Check("Client path plus exact active platform script is a portal candidate",SourceExplorerRules.PortalClient(Document(Portal,PortalHtml)));
        Check("Generic path and platform prose alone are not portal proof",!SourceExplorerRules.PortalClient(Document(Home+"article",PortalHtml))&&!SourceExplorerRules.PortalClient(Document(Portal,"<html><title>Ministra</title><p>STB setup guide</p></html>")));
        Check("Comment and inert markup cannot provide a portal fingerprint",new[]{"<!--{0}-->","<pre>{0}</pre>","<code>{0}</code>","<template>{0}</template>","<noscript>{0}</noscript>","<textarea>{0}</textarea>"}.All(wrapper=>!SourceExplorerRules.PortalClient(Document(Portal,"<html><title>Ministra</title>"+string.Format(wrapper,"<script src='xpcom.common.js'></script>")+"</html>"))));
        Check("Fingerprint requires exact script basename or loader path",!SourceExplorerRules.PortalClient(Document(Portal,PortalHtml.Replace("xpcom.common.js","notxpcom.common.js")))&&SourceExplorerRules.PortalClient(Document(Portal,PortalHtml.Replace("xpcom.common.js","../server/api/load_js.php"))));
        Check("Inline script string is not an external portal script",!SourceExplorerRules.PortalClient(Document(Portal,"<html><title>Ministra</title><script>let x=\"<script src='xpcom.common.js'>\";</script></html>")));
        Check("Plain text script source is not a portal fingerprint",!SourceExplorerRules.PortalClient(Document(Portal,"<html><title>Ministra</title><script type='text/plain' src='xpcom.common.js'></script></html>")));
        Check("Private prose labels and both encoding styles are blocked",new[]{"Password: fixture-secret","Hasło: fixture-secret","Cookie: fixture-secret","MAC: 02:00:00:00:00:01","\"password\":\"fixture-secret\"","Password&#58; fixture-secret","&#112;assword: fixture-secret","password%253A%2520fixture-secret"}.All(SourceExplorerRules.SensitiveText));
        Check("Normal channel title is not treated as a password",!SourceExplorerRules.SensitiveText("TV News — Polska"));
        Check("Credential-bearing page title is replaced with safe host",SourceExplorerRules.Title(Document(Home,"<title>Password&#58; fixture-secret</title>"))=="publisher.example");
        Check("Account APIs, path-info and privileged query keys are never landing pages",new[]{Home+"portal.php",Home+"portal.php/",Home+"player_api.php/extra",Home+"server/load.php",Home+"admin/",Home+"c/?%61ction=handshake",Home+"c/?debug_key=fixture",Home+"get.php?username=test&password=fixture-secret"}.All(u=>!SourceExplorerRules.AllowedUrl(u)));
        Check("Public ports and network boundaries stay restrictive",new[]{"http://127.0.0.1/c/","http://10.0.0.1/c/","http://[::1]/c/","https://public.example:8080/c/","https://user:fixture-secret@publisher.example/c/"}.All(u=>!SourceExplorerRules.AllowedUrl(u)));
        Check("Signed public media remains eligible but token landing pages do not",SourceExplorerRules.AllowedUrl("https://cdn.example/live.m3u8?token=public-signature&key=public-key")&&!SourceExplorerRules.AllowedUrl(Home+"landing?token=fixture-secret"));
        Check("Portal frontend normalization preserves an explicit routing prefix",PortalAddress.Endpoint(Home+"prefix/stalker_portal/c/index.html")==Home+"prefix/stalker_portal/server/load.php");
        await Case("Octet-stream MPD with UTF8 BOM reaches the bounded XML parser",async()=>{string body="\uFEFF"+Dash.Replace("<AdaptationSet>","<AdaptationSet><ContentProtection schemeIdUri='urn:uuid:fixture'/>");var decoded=PublicWeb.DecodeDocument(Home+"live.mpd","application/octet-stream",Encoding.UTF8.GetBytes(body));var result=await Analyze(decoded,"live.mpd");return decoded==body&&result.Candidates.Single().RequiresDrm;});
        await Case("Octet-stream HLS remains a direct stream rather than a playlist",async()=>{var decoded=PublicWeb.DecodeDocument(Home+"live.m3u8?token=public-signature","application/octet-stream",Encoding.UTF8.GetBytes(Hls));var result=await Analyze(decoded,"live.m3u8");return decoded==Hls&&result.Candidates.Single().Kind==SourceCandidateKind.DirectStream&&result.Playlists.Count==0;});
        await Case("Binary octet-stream content is rejected at manifest URLs",()=>{bool rejected=false;try{PublicWeb.DecodeDocument(Home+"live.mpd","application/octet-stream",new byte[]{0,1,2,3,255,0});}catch(IOException){rejected=true;}return Task.FromResult(rejected);});
        await Case("Octet-stream documents on unrelated extensions remain rejected",()=>{bool rejected=false;try{PublicWeb.DecodeDocument(Home+"download.bin","application/octet-stream",Encoding.UTF8.GetBytes(Dash));}catch(IOException){rejected=true;}return Task.FromResult(rejected);});

        int redirectCase=0;
        foreach(string target in new[]{Home+"server/load.php?action=handshake",Home+"c/?%61ction=handshake",Home+"get.php?username=test&password=fixture-secret",Home+"portal.php/",Home+"c/?debug_key=fixture", "http://127.0.0.1/c/","https://public.example:8080/c/"})
        {
            await Case("Redirect policy blocks target before request "+(++redirectCase)+": "+(new Uri(target).Host=="publisher.example"?new Uri(target).AbsolutePath:new Uri(target).Host),async()=>{
                int sent=0;bool rejected=false;
                Task<PublicWebResponse> Send(string url,CancellationToken ct){sent++;return Task.FromResult(new PublicWebResponse(302,target,null));}
                try{await PublicWeb.FetchChecked(Home+"start",CancellationToken.None,SourceExplorerRules.AllowedUrl,Send);}catch(IOException){rejected=true;}
                return rejected&&sent==1;
            });
        }
        await Case("Safe public redirect keeps destination provenance",async()=>{
            int sent=0;Task<PublicWebResponse> Send(string url,CancellationToken ct){sent++;return Task.FromResult(sent==1?new PublicWebResponse(302,"/final",null):new PublicWebResponse(200,"",Document(url,"<html>Public TV</html>")));}
            var result=await PublicWeb.FetchChecked(Home+"start",CancellationToken.None,SourceExplorerRules.AllowedUrl,Send);return sent==2&&result.Url==Home+"final";
        });
        await Case("Redirect loops stay within existing five-request bound",async()=>{
            int sent=0;bool rejected=false;Task<PublicWebResponse> Send(string url,CancellationToken ct){sent++;return Task.FromResult(new PublicWebResponse(302,"/loop",null));}
            try{await PublicWeb.FetchChecked(Home+"start",CancellationToken.None,SourceExplorerRules.AllowedUrl,Send);}catch(IOException){rejected=true;}return rejected&&sent==5;
        });
        await Case("Portal classification never downloads the marker script or API",async()=>{
            var visits=new List<string>();var explorer=new SourceExplorer((u,c)=>{visits.Add(u);return Task.FromResult(Document(u,PortalHtml));});var result=await explorer.Analyze(Portal,[],[],CancellationToken.None);
            return visits.SequenceEqual(new[]{Portal})&&result.Candidates.Single().Kind==SourceCandidateKind.PortalCandidate&&result.Playlists.Count==0;
        });
        await Case("Mixed playlist removes account entries and keeps public signed CDN",async()=>{
            string mixed=Playlist+"#EXTINF:-1,Private\nhttps://cdn.example/live/account/password/123.ts\n#EXTINF:-1,Public signed\nhttps://cdn.example/signed.m3u8?token=public-signature\n";
            var result=await Analyze(mixed,"channels.m3u");var list=result.Playlists.Single();return list.SourceCount==2&&list.RemovedEntries==1&&list.Sanitized&&!list.OriginalM3u.Contains("/account/password/")&&list.OriginalM3u.Contains("token=public-signature")&&result.Candidates.Single().Kind==SourceCandidateKind.PublicPlaylist;
        });
        await Case("HLS is a direct candidate, never a channel playlist",async()=>{var r=await Analyze(Hls,"live.m3u8");return r.Playlists.Count==0&&r.Candidates.Single().Kind==SourceCandidateKind.DirectStream&&!r.Candidates.Single().RequiresDrm;});
        await Case("HLS session protection and single-quoted key format are labelled DRM",async()=>{var r=await Analyze(Hls+"#EXT-X-SESSION-KEY:METHOD=SAMPLE-AES,KEYFORMAT='com.widevine',URI='https://license.example/public'\n","live.m3u8");return r.Candidates.Single().RequiresDrm;});
        await Case("Public identity AES key is not mislabelled commercial DRM",async()=>{var r=await Analyze(Hls+"#EXT-X-KEY:METHOD=AES-128,KEYFORMAT='identity',URI='https://cdn.example/key.bin'\n","live.m3u8");return !r.Candidates.Single().RequiresDrm;});
        await Case("HLS account URI is excluded before any native handoff",async()=>{var r=await Analyze(Hls.Replace("https://cdn.example/one.ts","https://cdn.example/live/account/password/123.ts"),"live.m3u8");return r.Candidates.Count==0;});
        await Case("DASH protection is parsed without fetching license or segments",async()=>{var r=await Analyze(Dash.Replace("<AdaptationSet>","<AdaptationSet><ContentProtection schemeIdUri='urn:uuid:fixture'/>"),"live.mpd");return r.Candidates.Single().RequiresDrm&&r.Playlists.Count==0;});
        await Case("DASH account BaseURL is excluded from public playback candidates",async()=>{var r=await Analyze(Dash.Replace("https://cdn.example/video.mp4","https://cdn.example/live/account/password/123.ts"),"live.mpd");return r.Candidates.Count==0;});
        await Case("Malformed DASH and XML external entities do not create candidates",async()=>{var broken=await Analyze("<MPD><broken","bad.mpd");var dtd=await Analyze("<!DOCTYPE MPD [<!ENTITY x SYSTEM 'file:///fixture'>]><MPD>&x;</MPD>","bad.mpd");return broken.Candidates.Count==0&&dtd.Candidates.Count==0;});
        await Case("Stale and future playlists cannot become fresh candidates",async()=>{var old=await Analyze(Playlist,"old.m3u",DateTimeOffset.UtcNow.AddDays(-8));var future=await Analyze(Playlist,"future.m3u",DateTimeOffset.UtcNow.AddHours(1));return old.Candidates.Count==0&&future.Candidates.Count==0&&old.Playlists.Count==0&&future.Playlists.Count==0;});
        await Case("HTML containing published account data is not a source of portal links",async()=>{var r=await Analyze("<html><title>Public TV</title><p>MAC: 02:00:00:00:00:01 Password: fixture-secret</p><a href='/stalker_portal/c/'>TV</a></html>");return r.Candidates.Count==0;});
        Check("Iframe source is extracted independently of anchor endings",SourceExplorerRules.Links(Document(Home,"<html><iframe src='/player/live'></iframe><p>"+new string('x',3000)+"</p></html>")).Contains(Home+"player/live"));
        Check("Published plain M3U in a code example remains discoverable",SourceExplorerRules.Links(Document(Home,"<html><pre><code>https://cdn.example/channels/public.m3u</code></pre></html>")).Contains("https://cdn.example/channels/public.m3u"));
        Check("Navigation links cannot crowd out a published playlist",SourceExplorerRules.Links(Document(Home,"<html>"+string.Join("",Enumerable.Range(0,150).Select(i=>$"<a href='/navigation/{i}'>Menu</a>"))+"<a href='https://cdn.example/channels/public.m3u'>Public playlist</a></html>")).Contains("https://cdn.example/channels/public.m3u"));
        Check("Account URL in a code example cannot become a public discovery link",!SourceExplorerRules.Links(Document(Home,"<html><pre><code>https://cdn.example/get.php?username=fixture&amp;password=fixture-secret&amp;type=m3u\nhttps://cdn.example/live/fixture/password/123.m3u8</code></pre></html>")).Any());
        Check("Published encoded path and signed query remain byte-identical after link extraction",SourceExplorerRules.Links(Document(Home,"<html><a href='https://cdn.example/path%2Fprefix/list.m3u?token=a%2Bb%2Fc&amp;signature=public'>Playlist</a></html>")).Contains("https://cdn.example/path%2Fprefix/list.m3u?token=a%2Bb%2Fc&signature=public"));
        await Case("Published README playlist is fetched before abundant navigation",async()=>{var visited=new List<string>();var explorer=new SourceExplorer((u,c)=>{visited.Add(u);return Task.FromResult(Document(u,u.EndsWith("public.m3u")?Playlist:"<html>"+string.Join("",Enumerable.Range(0,150).Select(i=>$"<a href='/navigation/{i}'>Menu</a>"))+"<pre>https://cdn.example/public.m3u</pre></html>"));});var result=await explorer.Analyze(Home,[],[],CancellationToken.None);return result.Playlists.Count==1&&visited[1]=="https://cdn.example/public.m3u"&&result.Candidates.Any(c=>c.Kind==SourceCandidateKind.PublicPlaylist);});
        Check("RSS descriptions containing credentials prevent public hits",SourceExplorerRules.SearchHits("<rss><channel><item><title>Provider</title><link>https://publisher.example/c/</link><description>Password: fixture-secret</description></item><item><title>Public TV</title><link>https://publisher.example/live</link><description>Official television</description></item></channel></rss>",false).Select(h=>h.Url).SequenceEqual(new[]{Home+"live"}));
        Check("Duck snippets containing credentials prevent public hits",SourceExplorerRules.SearchHits("<div><a class='result__a' href='https://publisher.example/c/'>Provider</a><p class='result__snippet'>Password: fixture-secret</p></div><div><a class='result__a' href='https://publisher.example/live'>Public TV</a><p>Official television</p></div>",true).Select(h=>h.Url).SequenceEqual(new[]{Home+"live"}));
        await Case("Private search input causes zero requests",async()=>{int requests=0;var explorer=new SourceExplorer((u,c)=>{requests++;throw new IOException();});bool rejected=false;try{await explorer.Search("Password%3A%20fixture-secret",[],[],CancellationToken.None);}catch(InvalidDataException){rejected=true;}return rejected&&requests==0;});
        await Case("Pre-cancelled scan causes zero requests",async()=>{int requests=0;var explorer=new SourceExplorer((u,c)=>{requests++;return Task.FromResult(Document(u,PortalHtml));});using var cancel=new CancellationTokenSource();cancel.Cancel();bool rejected=false;try{await explorer.Analyze(Portal,[],[],cancel.Token);}catch(OperationCanceledException){rejected=true;}return rejected&&requests==0;});
        await Case("Cancellation after a slow transport prevents returned results",async()=>{using var cancel=new CancellationTokenSource();var explorer=new SourceExplorer((u,c)=>{cancel.Cancel();return Task.FromResult(Document(u,PortalHtml));});bool rejected=false;try{await explorer.Analyze(Portal,[],[],cancel.Token);}catch(OperationCanceledException){rejected=true;}return rejected;});
        await Case("Page budget prevents unbounded link traversal",async()=>{var visits=new List<string>();var explorer=new SourceExplorer((u,c)=>{visits.Add(u);string links=u==Home?string.Join("",Enumerable.Range(0,80).Select(i=>$"<a href='/page{i}'>Public TV {i}</a>")):"";return Task.FromResult(Document(u,"<html><title>TV</title>"+links+"</html>"));});var r=await explorer.Analyze(Home,[],[],CancellationToken.None);return visits.Count==SourceExplorer.MaxPages&&visits.Distinct().Count()==visits.Count&&r.Candidates.Count<=SourceExplorer.MaxResults;});
        await Case("Depth budget stops before third nested page",async()=>{var visits=new List<string>();var explorer=new SourceExplorer((u,c)=>{visits.Add(u);int depth=u==Home?0:int.Parse(new Uri(u).AbsolutePath.Trim('/'));return Task.FromResult(Document(u,$"<html><title>TV</title><a href='/{depth+1}'>Next</a></html>"));});await explorer.Analyze(Home,[],[],CancellationToken.None);return visits.Count==SourceExplorer.MaxDepth+1&&!visits.Contains(Home+"3");});
        await Case("Duplicate search hits are fetched only once within bounded search",async()=>{int search=0,pages=0;var explorer=new SourceExplorer((u,c)=>{if(new Uri(u).Host=="publisher.example"){pages++;return Task.FromResult(Document(u,"<html><title>TV</title></html>"));}search++;return Task.FromResult(Document(u,u.Contains("bing.com")?"<rss><channel><item><title>Public TV</title><link>https://publisher.example/</link></item></channel></rss>":"<a class='result__a' href='https://publisher.example/'>Public TV</a>"));});await explorer.Search("Public television",["PL"],[],CancellationToken.None);return pages==1&&search<=SourceExplorer.MaxQueries;});

        await Case("Per-profile store isolates results and retains discovery dates",()=>{string a=Path.Combine(root,"profile-a"),b=Path.Combine(root,"profile-b");var row=Candidate(Home+"saved") with{CheckedAt=DateTimeOffset.UtcNow.AddDays(-1)};new SourceExplorerStore(a).Merge(Batch(row));var restored=new SourceExplorerStore(a);return Task.FromResult(restored.Items.Single().CheckedAt==row.CheckedAt&&new SourceExplorerStore(b).Items.Count==0);});
        await Case("Failed or empty refresh does not replace an existing source set",()=>{var store=new SourceExplorerStore(Path.Combine(root,"retention"));store.Merge(Batch(Candidate(Home+"saved")));store.Merge(new([],[],[],true));store.Merge(new([Candidate(Home+"partial")],[],[],false));return Task.FromResult(store.Items.Count==1&&store.Items[0].Url==Home+"saved");});
        await Case("Invalid incoming account candidate cannot mutate a good store",()=>{var store=new SourceExplorerStore(Path.Combine(root,"validation"));store.Merge(Batch(Candidate(Home+"saved")));bool rejected=false;try{store.Merge(Batch(Candidate(Home+"get.php?username=fixture&password=fixture-secret")));}catch(InvalidDataException){rejected=true;}return Task.FromResult(rejected&&store.Items.Count==1);});
        await Case("Encrypted explorer cache does not expose stored URLs or titles",()=>{string folder=Path.Combine(root,"encryption");new SourceExplorerStore(folder).Merge(Batch(Candidate(Home+"private-metadata-marker","Unique fixture title")));string raw=Encoding.Latin1.GetString(File.ReadAllBytes(Path.Combine(folder,"source-explorer.dpapi")));return Task.FromResult(!raw.Contains("publisher.example")&&!raw.Contains("Unique fixture title"));});
        await Case("Backup recovery survives two subsequent saves without replacing good backup with corruption",()=>{string folder=Path.Combine(root,"recovery");var store=new SourceExplorerStore(folder);store.Merge(Batch(Candidate(Home+"one")));store.Merge(Batch(Candidate(Home+"two")));string path=Path.Combine(folder,"source-explorer.dpapi");File.WriteAllText(path,"fixture corrupt main");var recovered=new SourceExplorerStore(folder);if(recovered.Items.Count!=1||recovered.Notice.Length==0)return Task.FromResult(false);recovered.Merge(Batch(Candidate(Home+"three")));recovered.Merge(Batch(Candidate(Home+"four")));var backup=PrivateData.Read<List<SourceCandidate>>(path+".bak","source-explorer-v1");return Task.FromResult(backup.Count==2&&backup.Any(c=>c.Url==Home+"one")&&backup.Any(c=>c.Url==Home+"three"));});
        await Case("Unrecoverable cache is retained rather than silently overwritten",()=>{string folder=Path.Combine(root,"unrecoverable");Directory.CreateDirectory(folder);string path=Path.Combine(folder,"source-explorer.dpapi");File.WriteAllText(path,"fixture damaged");var store=new SourceExplorerStore(folder);bool rejected=false;try{store.Merge(Batch(Candidate(Home+"new")));}catch(InvalidDataException){rejected=true;}return Task.FromResult(rejected&&File.ReadAllText(path)=="fixture damaged");});

        if(network)
        {
            await Case("Public Infomir-published legacy demo frontend is identified without authentication",async()=>{using var cancel=new CancellationTokenSource(TimeSpan.FromSeconds(30));var r=await new SourceExplorer().Analyze("http://middleware-stalker.com/stalker_portal/c/",[],[],cancel.Token);var c=r.Candidates.SingleOrDefault(x=>x.Kind==SourceCandidateKind.PortalCandidate);return c!=null&&c.ModifiedAt!=null&&c.CheckedAt>DateTimeOffset.UtcNow.AddMinutes(-2)&&r.Playlists.Count==0;});
            await Case("Fresh actual PL playlist parses with sanitized public provenance",async()=>{using var cancel=new CancellationTokenSource(TimeSpan.FromSeconds(30));var r=await new SourceExplorer().Analyze("https://iptv-org.github.io/iptv/countries/pl.m3u",["PL"],[],cancel.Token);var p=r.Playlists.Single();return r.Candidates.Single().Kind==SourceCandidateKind.PublicPlaylist&&p.SourceCount>100&&p.OriginalSha256.Length==64&&p.ModifiedAt>DateTimeOffset.UtcNow.AddDays(-7)&&p.Stations.All(s=>!PublicPlaylistPrivacy.ContainsCredentials(s.Url));});
            await Case("Official Shaka ClearKey MPD is labelled protected without requesting a license",async()=>{using var cancel=new CancellationTokenSource(TimeSpan.FromSeconds(30));var requests=new List<string>();var explorer=new SourceExplorer(async(u,c)=>{requests.Add(u);return await PublicWeb.FetchChecked(u,c,SourceExplorerRules.AllowedUrl);});const string url="https://storage.googleapis.com/shaka-demo-assets/angel-one-clearkey/dash.mpd";var r=await explorer.Analyze(url,[],[],cancel.Token);return r.Candidates.Single().Kind==SourceCandidateKind.DirectStream&&r.Candidates.Single().RequiresDrm&&requests.SequenceEqual(new[]{url});});
        }
        File.WriteAllText(full,JsonSerializer.Serialize(new{success,atUtc=DateTimeOffset.UtcNow,network,fixtureOnlyCredentials=true,portalAuthenticationAttempted=false,playbackClaim=false,checks},new JsonSerializerOptions{WriteIndented=true}));
        return success?0:1;
    }
}
